### 4.3 Mock Exchange Connectors

**Problem**: No way to test without real exchanges

**Solution**: Create `MockConnector` implementing `ExchangeConnector`

```rust
// crates/exchange-connectors/src/mock.rs

#[derive(Debug, Clone)]
pub struct MockConnector {
    id: ExchangeId,
    config: ConnectorConfig,
    order_books: Arc<RwLock<HashMap<Symbol, OrderBook>>>,
    tickers: Arc<RwLock<HashMap<Symbol, Ticker>>>,
    latency_ms: u64,
    should_fail: Arc<AtomicBool>,
    connection_status: Arc<AtomicU8>,
}

impl MockConnector {
    pub fn with_latency(ms: u64) -> Self {
        Self {
            latency_ms: ms,
            ..Self::default()
        }
    }

    pub fn with_failure() -> Self {
        Self {
            should_fail: Arc::new(AtomicBool::new(true)),
            ..Self::default()
        }
    }

    pub fn set_order_book(&self, book: OrderBook) {
        self.order_books.write().unwrap().insert(book.symbol.clone(), book);
    }

    pub fn set_ticker(&self, ticker: Ticker) {
        self.tickers.write().unwrap().insert(ticker.symbol.clone(), ticker);
    }

    pub fn inject_failure(&self) {
        self.should_fail.store(true, Ordering::SeqCst);
    }

    pub fn clear_failure(&self) {
        self.should_fail.store(false, Ordering::SeqCst);
    }
}

#[async_trait]
impl ExchangeConnector for MockConnector {
    fn id(&self) -> ExchangeId {
        self.id
    }

    fn config(&self) -> &ConnectorConfig {
        &self.config
    }

    async fn connect(&mut self) -> Result<()> {
        if self.should_fail.load(Ordering::SeqCst) {
            return Err(ArbitrageError::Exchange {
                exchange: self.id,
                operation: "connect".to_string(),
                details: "Injected failure".to_string(),
            });
        }
        self.connection_status.store(1, Ordering::SeqCst); // Connected
        Ok(())
    }

    async fn disconnect(&mut self) -> Result<()> {
        self.connection_status.store(0, Ordering::SeqCst); // Disconnected
        Ok(())
    }

    async fn subscribe_order_book(&mut self, symbols: &[Symbol]) -> Result<()> {
        if self.should_fail.load(Ordering::SeqCst) {
            return Err(ArbitrageError::Exchange {
                exchange: self.id,
                operation: "subscribe".to_string(),
                details: "Injected failure".to_string(),
            });
        }
        Ok(())
    }

    async fn get_order_book(&self, symbol: &Symbol) -> Result<OrderBook> {
        if self.latency_ms > 0 {
            tokio::time::sleep(Duration::from_millis(self.latency_ms)).await;
        }
        if self.should_fail.load(Ordering::SeqCst) {
            return Err(ArbitrageError::Exchange {
                exchange: self.id,
                operation: "get_order_book".to_string(),
                details: "Injected failure".to_string(),
            });
        }
        self.order_books
            .read()
            .unwrap()
            .get(symbol)
            .cloned()
            .ok_or_else(|| ArbitrageError::Exchange {
                exchange: self.id,
                operation: "get_order_book".to_string(),
                details: format!("No order book for {}", symbol),
            })
    }

    fn status(&self) -> ConnectionStatus {
        match self.connection_status.load(Ordering::SeqCst) {
            1 => ConnectionStatus::Connected,
            _ => ConnectionStatus::Disconnected,
        }
    }
}
```

