**Proptest strategies**:
```rust
proptest! {
    #[test]
    fn test_profit_bps_never_panics(buy in "[0-9]{1,8}\\.[0-9]{1,8}",
                                     sell in "[0-9]{1,8}\\.[0-9]{1,8}") {
        let buy: Decimal = buy.parse().unwrap();
        let sell: Decimal = sell.parse().unwrap();
        // Should never panic
        let _ = calculate_profit_bps(buy, sell);
    }

    #[test]
    fn test_vwap_between_bid_ask(bid in "[0-9]{1,8}\\.[0-9]{1,8}",
                                  ask in "[0-9]{1,8}\\.[0-9]{1,8}") {
        let bid: Decimal = bid.parse().unwrap();
        let ask: Decimal = ask.parse().unwrap();
        let vwap = (bid + ask) / Decimal::from(2);
        prop_assert!(bid <= vwap && vwap <= ask);
    }
}
```

**Target**: +100 property tests

