use criterion::{black_box, criterion_group, criterion_main, Criterion};

fn benchmark_profit_calculation(c: &mut Criterion) {
    c.bench_function("profit_bps_10k_iterations", |b| {
        b.iter(|| {
            for _ in 0..10000 {
                let _ = calculate_profit_bps(
                    black_box(Decimal::from(50000)),
                    black_box(Decimal::from(50100)),
                );
            }
        })
    });
}

fn benchmark_vwap_calculation(c: &mut Criterion) {
    let order_book = TestFixtures::order_book()
        .symbol("BTC", "USDT")
        .depth(100)
        .build();

    c.bench_function("vwap_100_levels", |b| {
        b.iter(|| order_book.calculate_vwap())
    });
}

criterion_group!(benches, benchmark_profit_calculation, benchmark_vwap_calculation);
criterion_main!(benches);
```

**Target**: +50 benchmarks

